struct RuntimeScriptsPlugin: Plugin {
    let scriptURL: URL

    @MainActor
    func setup(in app: borrowing AppWorlds) {
        do {
            let script = try AdaScriptPlugin(contentsOf: scriptURL)
            app.addPlugin(script)
        } catch {
            print("Could not load Ada Script: \(error)")
        }
    }
}

