@system(scheduler: "update")
class TargetingSystem {
    @query(Player, Transform)
    var players;

    @query(Enemy, Target, without: Dead)
    var enemies;

    func update(context) {
        for (var enemy in enemies) {
            for (var player in players) {
                enemy.target.entity = player.id;
                break;
            }
        }
    }
}

